// Parse voice synthesis request
const requestData = JSON.parse($input.first().json.body);

// Validate required fields
if (!requestData.text || !requestData.voiceConfig) {
  throw new Error('Missing required fields: text and voiceConfig');
}

// Prepare voice synthesis data
const synthesisData = {
  text: requestData.text,
  voiceConfig: {
    race: requestData.voiceConfig.race || 'human',
    gender: requestData.voiceConfig.gender || 'neutral',
    age: requestData.voiceConfig.age || 'adult',
    socialClass: requestData.voiceConfig.socialClass || 'common',
    accent: requestData.voiceConfig.accent || 'standard',
    characteristics: requestData.voiceConfig.characteristics || [],
    environment: requestData.voiceConfig.environment || 'neutral'
  },
  emotionalState: requestData.emotionalState || {},
  options: {
    provider: requestData.provider || 'elevenlabs',
    quality: requestData.quality || 'high',
    realtime: requestData.realtime || false,
    language: requestData.language || 'en'
  },
  metadata: {
    requestId: generateRequestId(),
    timestamp: new Date().toISOString(),
    source: 'dialogue-system',
    priority: requestData.priority || 'normal'
  }
};

function generateRequestId() {
  return 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
}

// Add context information
synthesisData.context = {
  conversationId: requestData.conversationId,
  speakerId: requestData.speakerId,
  previousMessages: requestData.previousMessages || [],
  campaign: requestData.campaign || {},
  environment: requestData.environment || {}
};

return { json: synthesisData };

// Process voice synthesis results
const synthesisResult = $input.first().json;
const originalRequest = items[0].json; // Get original request data

// Prepare response data
const voiceResponse = {
  requestId: originalRequest.metadata.requestId,
  audioData: synthesisResult.audioBuffer || synthesisResult.audioData,
  format: synthesisResult.format || 'mp3',
  duration: synthesisResult.duration || 0,
  voiceConfig: originalRequest.voiceConfig,
  emotionalState: originalRequest.emotionalState,
  synthesis: {
    provider: synthesisResult.provider || originalRequest.options.provider,
    processingTime: synthesisResult.processingTime || 0,
    quality: synthesisResult.quality || originalRequest.options.quality,
    realtime: originalRequest.options.realtime,
    success: synthesisResult.success !== false,
    cacheHit: synthesisResult.cached || false
  },
  metadata: {
    synthesizedAt: new Date().toISOString(),
    textLength: originalRequest.text.length,
    sampleRate: synthesisResult.sampleRate || 22050,
    channels: synthesisResult.channels || 1,
    bitrate: synthesisResult.bitrate || 128000
  }
};

// Add audio processing information if available
if (synthesisResult.postProcessing) {
  voiceResponse.postProcessing = {
    ageCharacteristics: synthesisResult.postProcessing.ageApplied || false,
    environmentalEffects: synthesisResult.postProcessing.environmentApplied || false,
    vocalCharacteristics: synthesisResult.postProcessing.characteristicsApplied || false
  };
}

// Add voice profile information
voiceResponse.voiceProfile = {
  baseVoice: synthesisResult.voiceProfile?.baseVoice || 'standard',
  pitch: synthesisResult.voiceProfile?.pitch || 1.0,
  speed: synthesisResult.voiceProfile?.speed || 1.0,
  tone: synthesisResult.voiceProfile?.tone || 'neutral',
  accent: synthesisResult.voiceProfile?.accent || 'standard'
};

// Add emotional tone information
if (originalRequest.emotionalState && Object.keys(originalRequest.emotionalState).length > 0) {
  const dominantEmotion = Object.entries(originalRequest.emotionalState)
    .sort((a, b) => b[1] - a[1])[0]?.[0] || 'neutral';

  voiceResponse.emotionalTone = {
    dominant: dominantEmotion,
    intensity: originalRequest.emotionalState[dominantEmotion] || 0.5,
    applied: synthesisResult.emotionalModulationApplied || false
  };
}

return { json: voiceResponse };

// Process real-time audio streaming
const voiceResponse = $input.first().json;

// Prepare streaming response for real-time applications
const streamingData = {
  type: 'audio_stream',
  requestId: voiceResponse.requestId,
  streamData: {
    audioData: voiceResponse.audioData,
    format: voiceResponse.format,
    chunkSize: 1024, // bytes
    sampleRate: voiceResponse.metadata.sampleRate,
    channels: voiceResponse.metadata.channels
  },
  streaming: {
    protocol: 'websocket',
    endpoint: `/ws/audio-stream/${voiceResponse.requestId}`,
    bufferSize: 8192,
    lowLatency: true
  },
  metadata: {
    timestamp: new Date().toISOString(),
    latency: voiceResponse.synthesis.processingTime,
    estimatedTotalTime: voiceResponse.duration
  }
};

// Generate stream initialization packet
const initPacket = {
  type: 'stream_init',
  requestId: voiceResponse.requestId,
  config: {
    format: voiceResponse.format,
    sampleRate: voiceResponse.metadata.sampleRate,
    channels: voiceResponse.metadata.channels,
    bitrate: voiceResponse.metadata.bitrate
  },
  estimatedDuration: voiceResponse.duration
};

return { 
  json: {
    ...voiceResponse,
    streamingData,
    initPacket
  }
};

// Prepare standard audio file response
const voiceResponse = $input.first().json;

// Generate download URL for audio file
const downloadUrl = `/api/voice/download/${voiceResponse.requestId}`;
const previewUrl = `/api/voice/preview/${voiceResponse.requestId}`;

// Prepare file response data
const fileResponse = {
  ...voiceResponse,
  delivery: {
    type: 'file_download',
    downloadUrl,
    previewUrl,
    expiresAt: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString(), // 24 hours
    maxDownloads: 5
  },
  file: {
    name: `voice_${voiceResponse.requestId}.${voiceResponse.format}`,
    size: voiceResponse.audioData ? voiceResponse.audioData.length : 0,
    mimeType: `audio/${voiceResponse.format}`,
    encoding: 'base64'
  }
};

// Add quality metrics
fileResponse.qualityMetrics = {
  clarity: calculateAudioQuality(voiceResponse),
  naturalness: calculateNaturalness(voiceResponse),
  emotionalAccuracy: calculateEmotionalAccuracy(voiceResponse),
  overallScore: calculateOverallScore(voiceResponse)
};

function calculateAudioQuality(response) {
  // Placeholder for audio quality calculation
  return Math.min(1.0, 0.8 + Math.random() * 0.2);
}

function calculateNaturalness(response) {
  // Placeholder for naturalness calculation
  const providerBonus = response.synthesis.provider === 'elevenlabs' ? 0.1 : 0;
  const qualityBonus = response.synthesis.quality === 'high' ? 0.1 : 0;
  return Math.min(1.0, 0.7 + providerBonus + qualityBonus + Math.random() * 0.2);
}

function calculateEmotionalAccuracy(response) {
  // Calculate emotional tone accuracy
  if (!response.emotionalTone) return 0.5;

  const intensity = response.emotionalTone.intensity;
  const applied = response.emotionalTone.applied;
  const baseScore = 0.6;
  const intensityBonus = intensity * 0.3;
  const applicationBonus = applied ? 0.1 : 0;

  return Math.min(1.0, baseScore + intensityBonus + applicationBonus);
}

function calculateOverallScore(response) {
  const clarity = calculateAudioQuality(response);
  const naturalness = calculateNaturalness(response);
  const emotionalAccuracy = calculateEmotionalAccuracy(response);

  return (clarity * 0.4 + naturalness * 0.4 + emotionalAccuracy * 0.2);
}

return { json: fileResponse };
